#ifndef UTILITIES_ALARM_RECORDS_H
#define UTILITIES_ALARM_RECORDS_H
#include "AlarmServiceV1.h"
#include <stddef.h>
#include <string.h>
#define ALARM_RECORD_SIZE 32u
#ifdef ALARM_NATIVE_UTC
/* UTC seconds since 2000; native signed Unix seconds stop in January 2038. */
#define ALARM_RTC_MAX (2147483647u-946684800u)
#else
#define ALARM_RTC_MAX 3155759999u
#endif
#define ALARM_COUNTDOWN_MAX 359999u /* 99:59:59 */
#define ALARM_RECOVERY_SECONDS 60u
#define ALARM_INVOCATION_MS 20000u
#ifdef ALARM_NATIVE_UTC
#define ALARM_CONFIG_KEY "alarm_utc_cfg"
#define ALARM_TIMER_KEY "timer_utc_cfg"
#define ALARM_OCCURRENCE_KEY "alarm_utc_occ"
#define ALARM_TIMER_OCCURRENCE_KEY "timer_utc_occ"
#else
#define ALARM_CONFIG_KEY "alarm_cfg"
#define ALARM_TIMER_KEY "timer_cfg"
#define ALARM_OCCURRENCE_KEY "alarm_occ"
#define ALARM_TIMER_OCCURRENCE_KEY "timer_occ"
#endif
#define ALARM_MODE_KEY "alert_mode"
enum { ALARM_OCC_NONE, ALARM_OCC_PENDING, ALARM_OCC_ACKED, ALARM_OCC_EXPIRED };
typedef struct { uint32_t revision, deadline, created, duration; uint8_t kind, enabled; } alarm_config;
typedef struct { uint32_t revision, deadline, generation, recovery_until; uint8_t kind, state, mode, silenced; } alarm_occurrence;
static inline uint32_t alarm_read32(const uint8_t *p) {
    return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);
}
static inline void alarm_write32(uint8_t *p,uint32_t n) { for(unsigned i=0;i<4;i++){p[i]=(uint8_t)n;n>>=8;} }
static inline uint32_t alarm_checksum(const uint8_t *p) {
    uint32_t h=2166136261u;for(unsigned i=0;i<28;i++)h=(h^p[i])*16777619u;return h;
}
static inline bool alarm_config_valid(const alarm_config *r) {
    return r && r->kind>=1 && r->kind<=2 && r->enabled<=1 && r->revision &&
        r->created<=ALARM_RTC_MAX && r->deadline<=ALARM_RTC_MAX-ALARM_RECOVERY_SECONDS &&
        ((!r->enabled&&!r->deadline&&!r->duration) || (r->enabled && r->deadline>r->created &&
        (r->kind==ALARM_KIND_ALARM ? r->duration==0 : r->duration && r->duration<=ALARM_COUNTDOWN_MAX && r->deadline-r->created==r->duration)));
}
static inline void alarm_config_encode(const alarm_config *r,uint8_t b[ALARM_RECORD_SIZE]) {
    memset(b,0,ALARM_RECORD_SIZE);memcpy(b,"SAC1",4);b[4]=r->kind;b[5]=r->enabled;
    alarm_write32(b+8,r->revision);alarm_write32(b+12,r->deadline);alarm_write32(b+16,r->created);
    alarm_write32(b+20,r->duration);alarm_write32(b+28,alarm_checksum(b));
}
static inline bool alarm_config_decode(alarm_config *r,const uint8_t *b,uint32_t n,uint8_t kind) {
    if(!r||!b||n!=ALARM_RECORD_SIZE||memcmp(b,"SAC1",4)||b[4]!=kind||b[6]||b[7]||alarm_read32(b+24)||alarm_read32(b+28)!=alarm_checksum(b))return false;
    alarm_config v={alarm_read32(b+8),alarm_read32(b+12),alarm_read32(b+16),alarm_read32(b+20),b[4],b[5]};
    if(!alarm_config_valid(&v))return false;
    *r=v;return true;
}
static inline bool alarm_occurrence_valid(const alarm_occurrence *r) {
    return r&&r->kind>=1&&r->kind<=2&&r->state>=ALARM_OCC_PENDING&&r->state<=ALARM_OCC_EXPIRED&&
        r->mode>=1&&r->mode<=3&&r->silenced<=1&&r->revision&&r->generation&&r->deadline&&r->deadline<=ALARM_RTC_MAX-ALARM_RECOVERY_SECONDS&&
        r->recovery_until==r->deadline+ALARM_RECOVERY_SECONDS;
}
static inline void alarm_occurrence_encode(const alarm_occurrence *r,uint8_t b[ALARM_RECORD_SIZE]) {
    memset(b,0,ALARM_RECORD_SIZE);memcpy(b,r->silenced?"SAO2":"SAO1",4);b[4]=r->kind;b[5]=r->state;b[6]=r->mode;b[7]=r->silenced;
    alarm_write32(b+8,r->revision);alarm_write32(b+12,r->deadline);alarm_write32(b+16,r->generation);
    alarm_write32(b+20,r->recovery_until);alarm_write32(b+28,alarm_checksum(b));
}
static inline bool alarm_occurrence_decode(alarm_occurrence *r,const uint8_t *b,uint32_t n,uint8_t kind) {
    if(!r||!b||n!=ALARM_RECORD_SIZE||b[4]!=kind||alarm_read32(b+24)||alarm_read32(b+28)!=alarm_checksum(b))return false;
    if(!memcmp(b,"SAO1",4)?b[7]!=0:memcmp(b,"SAO2",4)||b[7]!=1)return false;
    alarm_occurrence v={alarm_read32(b+8),alarm_read32(b+12),alarm_read32(b+16),alarm_read32(b+20),b[4],b[5],b[6],b[7]};
    if(!alarm_occurrence_valid(&v))return false;
    *r=v;return true;
}
static inline bool alarm_calendar_seconds(uint16_t y,uint8_t m,uint8_t d,uint8_t h,uint8_t min,uint8_t s,uint32_t *out) {
    static const uint8_t days[]={31,28,31,30,31,30,31,31,30,31,30,31};
    if(!out||y<2000||y>2099||m<1||m>12||d<1||d>days[m-1]+(m==2&&y%4==0)||h>23||min>59||s>59)return false;
    uint32_t total=(uint32_t)(y-2000)*365u+(y-2000+3u)/4u;
    for(unsigned i=1;i<m;i++)total+=days[i-1]+(i==2&&y%4==0);
    *out=((total+d-1)*24u+h)*3600u+(uint32_t)min*60u+s;return true;
}
static inline bool alarm_same_occurrence(const alarm_occurrence *o,const alarm_config *c) {
    return o->state&&o->kind==c->kind&&o->revision==c->revision&&o->deadline==c->deadline;
}
static inline bool alarm_token_equal(const alarm_token_v1 *a,const alarm_token_v1 *b) {
    return a&&b&&a->kind==b->kind&&a->revision==b->revision&&a->deadline==b->deadline&&a->generation==b->generation;
}
#endif

#ifndef UTILITIES_ALARM_SERVICE_V1_H
#define UTILITIES_ALARM_SERVICE_V1_H
/* Utilities-owned, opaque-to-Runtime ordinary provider capability. */
#include <stdbool.h>
#include <stdint.h>
#define ALARM_SERVICE_CAPABILITY "alarm.service"
#define ALARM_SERVICE_API_V1 1u
#define ALARM_STATUS_CUE_SUPPORTED 1u
#define ALARM_KIND_ALARM 1u
#define ALARM_KIND_COUNTDOWN 2u
#define ALARM_MODE_VISUAL 0u /* Copied effective mode; never a persisted preference. */
#define ALARM_MODE_VIBRATE 1u
#define ALARM_MODE_SOUND 2u
#define ALARM_MODE_BOTH 3u
enum { ALARM_OK=0, ALARM_PENDING=1, ALARM_BUSY=-1, ALARM_INVALID=-2,
       ALARM_STALE=-3, ALARM_STORAGE=-4, ALARM_RTC=-5, ALARM_OUTPUT=-6,
       ALARM_EXHAUSTED=-7, ALARM_FOREGROUND=-8 };
enum { ALARM_STATE_LOADING, ALARM_STATE_READY, ALARM_STATE_ALERT,
       ALARM_STATE_DISMISSING, ALARM_STATE_BLOCKED,
       /* Additive copied status: non-modal output reservation, before open and
        * through cleanup. Updated clients must drain it without painting an
        * alarm overlay. Earlier clients reject unknown states safely. */
       ALARM_STATE_CUE };
enum { ALARM_SCHEDULE_OFF, ALARM_SCHEDULE_ARMED, ALARM_SCHEDULE_DUE,
       ALARM_SCHEDULE_DISMISSED, ALARM_SCHEDULE_EXPIRED };
typedef struct {
    uint32_t kind, revision, deadline, generation;
} alarm_token_v1;
typedef struct {
    uint32_t revision, deadline, state;
} alarm_schedule_status_v1;
typedef struct {
    uint32_t api_version, struct_size, state;
    int32_t error;
    uint32_t snapshot, rtc_seconds, mode, output_uncertain;
    alarm_schedule_status_v1 schedules[2];
    alarm_token_v1 occurrence;
    uint32_t recovery_until, remaining_ms;
    char label[24];
} alarm_status_v1;
typedef struct {
    uint32_t struct_size, snapshot, rtc_seconds, deadline;
    /* deadline=0 means no schedule. Decision is consumed immediately by the
       serialized caller, with no intervening service/writer call. */
} alarm_sleep_v1;
typedef struct {
    uint32_t api_version, struct_size;
    void *context;
    /* Memory-only copied values; caller sets struct_size. No retained pointers. */
    int32_t (*status)(void *, alarm_status_v1 *);
    /* One cooperative phase, at most two dependency calls (three with the DND
       preflight enabled). Explicit foreground
       safe point only; synchronous
       NVS has no hard latency guarantee. Never invoke from provider poll. */
    int32_t (*step)(void *);
    /* Memory-only hint; does not prove a writer commit. Also retries blocked
       storage/RTC reconciliation, without silently acknowledging an alert. */
    int32_t (*refresh)(void *);
    /* Queues exact-current dismissal. Fully dismissed only after status READY,
       matching schedule DISMISSED, safe output stop and verified durable ACK. */
    int32_t (*acknowledge)(void *, const alarm_token_v1 *);
    /* Starts/finishes a fresh reconciliation. PENDING means call step and retry.
       No suppression flag or retained sleep lease; service has no I/O poll. */
    int32_t (*prepare_sleep)(void *, alarm_sleep_v1 *);
    /* Failure-only cleanup while a foreground presentation is not settled.
       One stop/silence/close operation per call, no storage or output start.
       OK proves both outputs stopped, but does NOT acknowledge an occurrence.
       OUTPUT means retain the invocation/resources; no normal handoff. */
    int32_t (*stop_only)(void *);
} alarm_service_v1;
/* Optional append-only descriptor. The v1 function table/status layouts stay
 * unchanged. Legacy providers require both physical outputs; a visual-only
 * provider advertises zero and never resolves audio/haptic dependencies. */
typedef struct {
    alarm_service_v1 service;
    uint32_t output_modes; /* ALARM_MODE_VIBRATE | ALARM_MODE_SOUND, or zero. */
} alarm_service_outputs_v1;
static inline uint32_t alarm_service_output_modes(const alarm_service_v1 *service) {
    if(!service || service->api_version!=ALARM_SERVICE_API_V1 ||
       service->struct_size<sizeof(*service))return ALARM_MODE_VISUAL;
    if(service->struct_size<sizeof(alarm_service_outputs_v1))return ALARM_MODE_BOTH;
    return ((const alarm_service_outputs_v1 *)service)->output_modes&ALARM_MODE_BOTH;
}
#if defined(__cplusplus)
#define ALARM_STATIC_ASSERT static_assert
#else
#define ALARM_STATIC_ASSERT _Static_assert
#endif
ALARM_STATIC_ASSERT(sizeof(alarm_token_v1)==16,"alarm occurrence token ABI");
ALARM_STATIC_ASSERT(sizeof(alarm_status_v1)==104,"alarm copied status ABI");
ALARM_STATIC_ASSERT(sizeof(alarm_sleep_v1)==16,"alarm sleep decision ABI");
#if UINTPTR_MAX == UINT32_MAX
ALARM_STATIC_ASSERT(sizeof(alarm_service_v1)==36,"alarm service target ABI");
ALARM_STATIC_ASSERT(sizeof(alarm_service_outputs_v1)==40,"alarm output descriptor target ABI");
#endif
#undef ALARM_STATIC_ASSERT
#endif

